{
  "findings": [
    {
      "check_id": "AVD-AZU-0010",
      "title": "Network rules do not allow bypass for Microsoft Services",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "The 'bypass' argument is missing 'AzureServices', which prevents trusted Microsoft services from accessing the storage account when network rules are applied, potentially breaking dependent services."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Allow\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\", \"AzureServices\"]\n}",
  "fix_summary": "Added 'AzureServices' to the 'bypass' list in the storage account network rules to ensure trusted Microsoft services can access the storage account, complying with security best practices."
}
